import React from "react";
import "./SuperAdmin.css";

export default function SuperAdmin({ username, onLogout }) {
  return (
    <div className="superadmin-container">
      <header className="superadmin-header">
        <h1 className="header-title">TalkinPon - Super Administrador</h1>
        <button className="logout-btn" onClick={onLogout}>Cerrar sesión</button>
      </header>
      <main className="admin-main">
        <div className="admin-card">
          <h2 className="admin-welcome">Bienvenido, {username}</h2>
          <div className="admin-options">
            <div className="admin-option">Procesos Administrativos</div>
            <div className="admin-option">Ubicaciones</div>
            <div className="admin-option">Usuarios</div>
          </div>
        </div>
      </main>
    </div>
  );
}
